SELECT (SELECT count(*) FROM pragma_table_info('t1')) AS t1_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_table_info('t1') ORDER BY cid)) AS t1_names, (SELECT group_concat(name || ':' || pk, ',') FROM (SELECT name, pk FROM pragma_table_info('t1') WHERE pk>0 ORDER BY pk)) AS t1_primary_key, COALESCE((SELECT instr(upper(sql), 'WITHOUT ROWID')>0 FROM sqlite_schema WHERE type='table' AND name='t1'), 0) AS t1_without_rowid, (SELECT count(*) FROM pragma_index_xinfo('i1')) AS i1_columns, (SELECT count(*) FROM pragma_index_xinfo('i1') WHERE "key"=1) AS i1_key_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_index_xinfo('i1') WHERE "key"=1 ORDER BY seqno)) AS i1_key_names, (SELECT count(*) FROM pragma_table_info('t2')) AS t2_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_table_info('t2') ORDER BY cid)) AS t2_names, (SELECT group_concat(name || ':' || pk, ',') FROM (SELECT name, pk FROM pragma_table_info('t2') WHERE pk>0 ORDER BY pk)) AS t2_primary_key, (SELECT count(*) FROM pragma_index_xinfo('i2')) AS i2_columns, (SELECT count(*) FROM pragma_index_xinfo('i2') WHERE "key"=1) AS i2_key_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_index_xinfo('i2') WHERE "key"=1 ORDER BY seqno)) AS i2_key_names;